ps.pstext:
if !IsFeatureImplemented(FEAT_AA64) then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EffectiveHCR_EL2_NVx() IN {'xx1'} then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        Undefined();
    end;
elsif PSTATE.EL == EL2 then
    X{64}(t) = CNTHCTL_EL2();
elsif PSTATE.EL == EL3 then
    X{64}(t) = CNTHCTL_EL2();
end;

if !IsFeatureImplemented(FEAT_AA64) then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EffectiveHCR_EL2_NVx() IN {'xx1'} then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        Undefined();
    end;
elsif PSTATE.EL == EL2 then
    CNTHCTL_EL2() = X{64}(t);
elsif PSTATE.EL == EL3 then
    CNTHCTL_EL2() = X{64}(t);
end;

if !IsFeatureImplemented(FEAT_AA64) then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    X{64}(t) = CNTKCTL_EL1();
elsif PSTATE.EL == EL2 then
    if ELIsInHost(EL2) then
        X{64}(t) = CNTHCTL_EL2_VHE(CNTHCTL_EL2());
    else
        X{64}(t) = CNTKCTL_EL1();
    end;
elsif PSTATE.EL == EL3 then
    X{64}(t) = CNTKCTL_EL1();
end;

if !IsFeatureImplemented(FEAT_AA64) then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    CNTKCTL_EL1() = X{64}(t);
elsif PSTATE.EL == EL2 then
    if ELIsInHost(EL2) then
        CNTHCTL_EL2() = CNTHCTL_EL2_VHE(X{64}(t));
    else
        CNTKCTL_EL1() = X{64}(t);
    end;
elsif PSTATE.EL == EL3 then
    CNTKCTL_EL1() = X{64}(t);
end;
